import type { FilterForm } from 'models/Filters';

import {
  COMMERCIAL_RESULTS_PRESET_DRIVER_KEYS,
  COMMERCIAL_RESULTS_PRESET_FORM_TO_QUERY_KEY,
  COMMERCIAL_RESULTS_PRESET_QUERY_BRACKET_PREFIX,
} from './constants';

/**
 * Flat bracket query params for the commercial preset `GET` (tier refresh drivers).
 */
export function buildCommercialResultsPresetQueryParams(
  form: FilterForm,
  bracketPrefix: string = COMMERCIAL_RESULTS_PRESET_QUERY_BRACKET_PREFIX,
): Record<string, string> {
  const out: Record<string, string> = {};

  for (const key of COMMERCIAL_RESULTS_PRESET_DRIVER_KEYS) {
    const raw = form[key];
    if (raw === null || raw === undefined || raw === '') continue;
    if (String(raw).toUpperCase() === 'ALL') continue;
    const subKey = COMMERCIAL_RESULTS_PRESET_FORM_TO_QUERY_KEY[key] ?? key;
    out[`${bracketPrefix}[${subKey}]`] = String(raw);
  }

  return out;
}
